import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BgYyFVKz.js";const _=JSON.parse('{"title":"输出模板引擎：命名即元数据投影","description":"","frontmatter":{},"headers":[],"relativePath":"guide/10-output-template.md","filePath":"guide/10-output-template.md","lastUpdated":1786517801000}'),r={name:"guide/10-output-template.md"};function l(i,e,s,c,p,n){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="输出模板引擎-命名即元数据投影" tabindex="-1">输出模板引擎：命名即元数据投影 <a class="header-anchor" href="#输出模板引擎-命名即元数据投影" aria-label="Permalink to &quot;输出模板引擎：命名即元数据投影&quot;">​</a></h1><blockquote><p>本章属于 composite 层。前置：info_dict 数据总线与提取器骨架。 学完你能：用一句话讲清&quot;为什么 yt-dlp 不自己写文本代入器、而要把模板预编译成宿主原生格式化&quot;——以及这条编译路径换来了什么、付出了什么。</p></blockquote><h2 id="_1-为什么需要它" tabindex="-1">1. 为什么需要它 <a class="header-anchor" href="#_1-为什么需要它" aria-label="Permalink to &quot;1. 为什么需要它&quot;">​</a></h2><p>上一章把 <code>-f bestvideo+bestaudio/best</code> 这种格式选择串编译成了一棵 AST，靠它从 <code>info_dict.formats</code> 里挑出最终下载的格式。可挑完之后还留着一连串问号：这个文件该叫什么名字？终端标题栏要显示什么？下载完了要执行的 shell 命令里怎么填参数？</p><p>这些问题在第 4 章的胖字典里其实都有答案：<code>title</code>、<code>id</code>、<code>ext</code>、<code>upload_date</code>、<code>duration</code> 一应俱全，缺的只是一个「把字典里的字段投影成字符串」的统一办法。</p><p>想象一下用户批量下载几百个视频，最常见的诉求是：</p><ul><li>文件名按「标题-序号.扩展名」排好；</li><li>终端标题栏实时显示「下载 47%」之类的进度；</li><li>下载完跑一条 shell 命令把文件挪到对应目录。</li></ul><p>这三件事表面不同，本质都是同一件事：<strong>从同一份 <code>info_dict</code> 派生出一段字符串</strong>。如果各写各的，文件名要写一遍取值、转义、缺字段崩不崩；进度标题要再写一遍；命令还要再写一遍，而且这一路还得自己挡 shell 注入。</p><p>这个机制就是来解决这个矛盾的：模板语法要足够丰富（点遍历、备选、默认值、类型转换、日期），但又不想从零写一个文本代入器；命名、进度、命令应当共享同一套投影机制，让下载逻辑与输出彻底解耦。</p><h2 id="_2-核心思想" tabindex="-1">2. 核心思想 <a class="header-anchor" href="#_2-核心思想" aria-label="Permalink to &quot;2. 核心思想&quot;">​</a></h2><p><strong>把自定义的元数据投影模板预编译成宿主语言自带的字符串格式化形式，让宿主做最终代入——引擎自己只管「取值与类型转换」。</strong></p><p>引擎是<strong>编译器</strong>，不是<strong>代入器</strong>。它把模板里每个复杂的 <code>%(expr)type</code> 占位符都拆开：取出值、做转换，再把结果塞进一张扁平的取值表；同时把那个复杂占位符<strong>改写</strong>成宿主原生占位符（直接引用扁平表里那一条）。等所有占位符都被编译完，模板已经退化成一段普通的宿主格式串，剩下的宽度、精度、对齐、零填充、最终代入全部交给宿主语言自带的格式化去完成。</p><p>一句话：<strong>难的取值与转换全在编译期做完，代入期平凡。</strong></p><h2 id="_3-心智模型" tabindex="-1">3. 心智模型 <a class="header-anchor" href="#_3-心智模型" aria-label="Permalink to &quot;3. 心智模型&quot;">​</a></h2><p>把整条流水线当成一台「两阶段」机器：</p>',15)])])}const h=t(r,[["render",l]]);export{_ as __pageData,h as default};
